<script setup>
import {ref} from 'vue'
import {onShow,onReachBottom} from '@dcloudio/uni-app'
import {request} from '../../utils/request'
import {API_BASE_URL} from '../../utils/config'
import {useInteraction} from '../../composables/useInteraction'
import MediaVideo from '../../components/MediaVideo.vue'
const {reducedMotion}=useInteraction()
const rows=ref([]),counts=ref({}),total=ref(0),page=ref(1),filter=ref('all'),loading=ref(false),busy=ref(''),error=ref(''),expanded=ref('')
const filters=[{id:'all',label:'全部作品'},{id:'0',label:'待审核'},{id:'1',label:'已通过'},{id:'2',label:'已下架'}]
let sequence=0
const url=s=>/^https?:\/\//.test(s)?s:API_BASE_URL+s
const state=w=>Number(w.status)===0?'待审核':Number(w.status)===2?'已下架':Number(w.visible)===1?'社区公开':'仅自己可见'
async function load(more=false){if(more&&loading.value)return;const seq=++sequence;const next=more?page.value+1:1;loading.value=true;error.value='';try{const data=await request({url:'/api/works/mine',data:{page:next,...(filter.value==='all'?{}:{status:filter.value})}});if(seq!==sequence)return;rows.value=more?[...rows.value,...data.records]:data.records;counts.value=data.counts;total.value=Number(data.total);page.value=next}catch(e){if(seq===sequence){error.value=e.message||'作品读取失败，请重试';if(!more)rows.value=[]}}finally{if(seq===sequence)loading.value=false}}
function choose(id){if(busy.value)return;filter.value=id;expanded.value='';load()}
function openDetail(w){uni.navigateTo({url:'/pages/work/detail?id='+w.id})}
function create(){uni.navigateTo({url:'/pages/work/publish'})}
function withdraw(w){uni.showModal({title:'撤回这份作品？',content:'撤回后作品将从列表和社区移除，关联评论及互动记录也会移除。此操作无法恢复。',success:async r=>{if(!r.confirm||busy.value)return;busy.value=w.id;try{await request({url:'/api/works/'+w.id+'/withdraw',method:'POST'});expanded.value='';await load();uni.showToast({title:'作品已撤回',icon:'success'})}catch(e){error.value=e.message||'撤回失败，请重试'}finally{busy.value=''}}})}
onShow(()=>load());onReachBottom(()=>{if(rows.value.length<total.value)load(true)})
</script>
<template><view class="growth-page personal-works" :class="{'motion-reduced':reducedMotion}"><view class="portfolio-hero"><view><text class="growth-eyebrow">MY COLLECTION · 创作留痕</text><text class="growth-title">每一份作品，都属于你</text><text class="growth-subtitle">查看发布状态，也由你决定哪些表达继续被看见。</text></view><image src="/static/xiaozhi-happy.png" mode="aspectFit" class="companion"/></view><view class="portfolio-actions"><text class="growth-muted">{{counts.all||0}} 份作品 · 保留自己的节奏</text><button class="growth-button" @click="create">发布作品</button></view><scroll-view scroll-x class="filter-scroll"><view class="portfolio-filters"><button v-for="f in filters" :key="f.id" :class="{active:filter===f.id}" :disabled="!!busy" :aria-pressed="filter===f.id" @click="choose(f.id)">{{f.label}} {{counts[f.id]||0}}</button></view></scroll-view><view v-if="error" class="growth-error" role="alert">{{error}}<button class="growth-button secondary" @click="load()">重新读取</button></view><view v-if="loading&&!rows.length" class="growth-card"><view class="growth-skeleton"/><view class="growth-skeleton short"/><text class="growth-muted">正在整理作品…</text></view><view v-else-if="!rows.length&&!error" class="portfolio-empty"><image src="/static/brand/weave-scene.png" mode="aspectFit"/><text class="growth-card-title">{{filter==='all'?'你的创作故事，从这里开始':'这个分类暂时没有作品'}}</text><text class="growth-muted">作品不必完美，记录当下就有意义。</text><button v-if="filter!=='all'" class="growth-button secondary" @click="choose('all')">查看全部作品</button><button v-else class="growth-button" @click="create">记录第一份作品</button></view><view class="portfolio-grid"><view v-for="w in rows" :key="w.id" class="portfolio-card"><image v-if="w.coverUrl" :src="url(w.coverUrl)" mode="aspectFill" class="portfolio-cover" lazy-load/><view v-else class="portfolio-placeholder"><text>{{w.mediaType==='video'?'影像记录':'文字作品'}}</text><text class="placeholder-line">一针一线，一点一滴。</text></view><view class="portfolio-body"><view class="portfolio-meta"><text :class="['state',{pending:Number(w.status)===0,hidden:Number(w.status)===2}]">{{state(w)}}</text><text>{{String(w.createTime||'').slice(0,10)}}</text></view><text class="portfolio-title">{{w.title}}</text><text class="growth-muted">{{Number(w.anonymous)===1?'匿名展示':'昵称展示'}} · {{Number(w.visible)===1?'公开范围':'私密范围'}}</text><view v-if="Number(w.status)!==1" class="status-help">{{Number(w.status)===0?'正在等待审核，目前不会出现在社区。':'作品已下架，目前不会出现在社区。你仍可在这里查看或撤回。'}}</view><button class="portfolio-expand" :aria-expanded="expanded===w.id" @click="expanded=expanded===w.id?'':w.id">{{expanded===w.id?'收起内容 −':'查看作品内容 ＋'}}</button><view v-if="expanded===w.id" class="portfolio-detail"><MediaVideo v-if="w.mediaType==='video'&&w.videoUrl" :src="w.videoUrl" caption="我的创作视频"/><text>{{w.message||'这份作品暂未填写故事。'}}</text></view><view class="portfolio-bottom"><button v-if="Number(w.status)===1" class="text-action" @click="openDetail(w)">查看详情</button><text v-else class="growth-muted">{{Number(w.status)===0?'等待审核':'已停止展示'}}</text><button class="text-action withdraw" :disabled="!!busy" @click="withdraw(w)">{{busy===w.id?'撤回中…':'撤回作品'}}</button></view></view></view></view><button v-if="rows.length<total" class="growth-button secondary" :disabled="loading||!!busy" @click="load(true)">{{loading?'正在读取…':'加载更多作品'}}</button><text class="growth-foot">本系统不能替代专业心理咨询</text></view></template>
<style src="../../styles/growth.css"></style><style scoped>
.personal-works{max-width:1100px}.portfolio-hero{display:flex;align-items:center;gap:12rpx;background:linear-gradient(120deg,#e8efe4,#f6f1e5);border:1rpx solid #dfe7dc;border-radius:28rpx;padding:32rpx}.portfolio-hero>view{flex:1}.companion{width:150rpx;height:180rpx;flex-shrink:0}.portfolio-actions{display:flex;align-items:center;justify-content:space-between;gap:20rpx;margin:28rpx 0}.portfolio-actions button{font-size:24rpx;padding:0 24rpx;margin:0}.filter-scroll{white-space:nowrap;margin-bottom:28rpx}.portfolio-filters{display:inline-flex;gap:12rpx}.portfolio-filters button{margin:0;padding:6rpx 20rpx;background:#e8efe4;color:#436350;font-size:24rpx;border-radius:14rpx}.portfolio-filters button.active{background:#2f7566;color:white}.portfolio-filters button::after,.text-action::after,.portfolio-expand::after{border:0}.portfolio-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:24rpx}.portfolio-card{min-width:0;background:white;border:1rpx solid #dfe7dc;border-radius:26rpx;overflow:hidden}.portfolio-cover{width:100%;height:280rpx}.portfolio-placeholder{height:180rpx;padding:36rpx;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;gap:14rpx;background:linear-gradient(130deg,#e8efe4,#f5f0e5);font-size:32rpx;color:#436350}.placeholder-line{font-size:23rpx;color:#586e62}.portfolio-body{padding:28rpx}.portfolio-meta{display:flex;justify-content:space-between;gap:12rpx;font-size:22rpx;color:#586e62}.state{color:#2f7566}.state.pending{color:#8c621e}.state.hidden{color:#8f584a}.portfolio-title{display:block;font-size:32rpx;line-height:1.6;font-weight:650;margin:18rpx 0;overflow-wrap:anywhere}.status-help{font-size:24rpx;line-height:1.8;color:#786858;background:#f8f3e9;border-radius:14rpx;padding:18rpx;margin-top:20rpx}.portfolio-expand{font-size:24rpx;color:#2f7566;background:transparent;text-align:left;padding:16rpx 0;margin-top:12rpx}.portfolio-detail{font-size:26rpx;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7f2;padding:20rpx;border-radius:16rpx}.portfolio-bottom{display:flex;align-items:center;justify-content:space-between;gap:12rpx;border-top:1rpx solid #dfe7dc;margin-top:18rpx;padding-top:18rpx}.text-action{background:transparent;color:#2f7566;padding:8rpx 0;margin:0;font-size:24rpx}.withdraw{color:#965347}.portfolio-empty{text-align:center;padding:36rpx;background:white;border-radius:26rpx;border:1rpx dashed #bdcfbf}.portfolio-empty image{height:200rpx;width:100%;margin-bottom:24rpx}@media(min-width:760px){.portfolio-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.portfolio-hero{padding:36px}.companion{width:150px;height:160px}.growth-title{font-size:32px}}
</style>
